<?php require_once __DIR__.'/../includes/functions.php';require_login(['mahasiswa']);$pdo=db();$studentId=student_id();$ta=$pdo->query("SELECT * FROM tahun_akademik WHERE status='Aktif' LIMIT 1")->fetch();if(!$ta)exit('Tidak ada tahun akademik aktif.');if(!$studentId)exit('Akun mahasiswa ini belum terhubung ke data mahasiswa.');if(isset($_GET['delete'])){if(!hash_equals(csrf(),$_GET['csrf']??''))exit('Permintaan tidak valid.');$pdo->prepare('DELETE FROM krs WHERE id=? AND id_mahasiswa=?')->execute([(int)$_GET['delete'],$studentId]);flash('success','Mata kuliah dihapus dari KRS.');redirect('mahasiswa/krs.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$kelas=(int)$_POST['kelas'];$q=$pdo->prepare('SELECT id,id_mk FROM kelas WHERE id=? AND id_tahun_akademik=?');$q->execute([$kelas,$ta['id']]);$k=$q->fetch();if(!$k){flash('error','Kelas tidak valid.');}else{try{$pdo->prepare('INSERT INTO krs(id_mahasiswa,id_mk,id_kelas,id_tahun_akademik) VALUES(?,?,?,?)')->execute([$studentId,$k['id_mk'],$kelas,$ta['id']]);flash('success','Mata kuliah berhasil ditambahkan.');}catch(PDOException $e){$sqlState=$e->errorInfo[0] ?? null;if($sqlState==='23000'){flash('error','Mata kuliah/kelas tersebut sudah ada di KRS Anda.');}else{flash('error','Gagal menyimpan KRS: '.$e->getMessage());}}}redirect('mahasiswa/krs.php');}$q=$pdo->prepare('SELECT k.id,mk.kode,mk.nama,mk.sks,kl.nama_kelas FROM krs k JOIN mata_kuliah mk ON mk.id=k.id_mk JOIN kelas kl ON kl.id=k.id_kelas WHERE k.id_mahasiswa=? AND k.id_tahun_akademik=?');$q->execute([$studentId,$ta['id']]);$rows=$q->fetchAll();$classes=$pdo->prepare('SELECT kl.id,kl.nama_kelas,m.kode,m.nama,m.sks,d.nama dosen FROM kelas kl JOIN mata_kuliah m ON m.id=kl.id_mk LEFT JOIN dosen d ON d.id=kl.id_dosen WHERE kl.id_tahun_akademik=?');$classes->execute([$ta['id']]);$classes=$classes->fetchAll();$page_title='KRS';require_once __DIR__.'/../includes/header.php';?>
<div class="d-flex justify-content-between mb-4"><div><h3>Kartu Rencana Studi</h3><p class="text-secondary mb-0"><?=e($ta['tahun'].' '.$ta['semester'])?></p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalKrs">Tambah Mata Kuliah</button></div><div class="card p-4"><table class="table"><thead><tr><th>Kode</th><th>Mata Kuliah</th><th>Kelas</th><th>SKS</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['kode'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=$r['sks']?></td><td><a class="btn btn-sm btn-outline-danger" href="?delete=<?=$r['id']?>&csrf=<?=csrf()?>">Hapus</a></td></tr><?php endforeach?></tbody><tfoot><tr><th colspan="3">Total SKS</th><th><?=array_sum(array_column($rows,'sks'))?></th><th></th></tr></tfoot></table></div><div class="modal fade" id="modalKrs"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h5 class="modal-title">Pilih Kelas</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=csrf_field()?><select required class="form-select" name="kelas"><option value="">Pilih mata kuliah / kelas</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['kode'].' — '.$c['nama'].' ('.$c['nama_kelas'].', '.$c['sks'].' SKS)')?></option><?php endforeach?></select></div><div class="modal-footer"><button class="btn btn-primary">Tambahkan</button></div></form></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
